inline std::atomic_bool enabled = defaults::kEnabled;
// NR insertion point (NRHookPoint).  kHookUpscaled (default) = "after": NR
// runs on the game's DLSS OUTPUT at display resolution.  kHookRender =
// "pre-SR": NR runs on the game's DLSS INPUT color at render resolution
// BEFORE the game's evaluate, so the NR network sees render-res color with
// resolution-matched depth/motion guides and the game's own DLSS upscales the
// already-enhanced image; it hard-requires guide resources that exactly match
// the color dimensions (else it declines for that frame and the game
// evaluates its own color).  kHookPresent (rc11): NR runs on the swapchain's
// back buffer at the present, before ReShade's effects and overlay, with the
// DLSS guides captured at the evaluate (present_path.hpp).  The three are
// mutually exclusive per frame.
inline constexpr uint32_t kHookUpscaled = 0;
inline constexpr uint32_t kHookRender = 1;
inline constexpr uint32_t kHookPresent = 2;
inline std::atomic_uint32_t hook_point = defaults::kHookPoint;
inline std::atomic_uint32_t auto_fg_fallback = defaults::kAutoFgFallback;
inline std::atomic_bool auto_fg_fallback_active{false};
// The pre-SR selection as the evaluate paths ask for it: a view of
// hook_point, so there is one stored insertion point.
struct PreSrSelection {
  bool load(std::memory_order = std::memory_order_seq_cst) const {
    return stages::Current().Count(stages::Point::Render) != 0
        && !screenshot::WantsFinalPresent();
  }
};
inline constexpr PreSrSelection nr_before_upscale{};
// The Present hook point's settings (defaults:: explains each).
inline std::atomic_uint32_t present_guides = defaults::kPresentGuides;
inline std::atomic_uint32_t present_encoding = defaults::kPresentEncoding;
inline std::atomic<float> present_white_nits = defaults::kPresentWhiteNits;
inline std::atomic_uint32_t present_white_source = defaults::kPresentWhiteSource;
inline std::atomic_bool present_ui_correction = defaults::kPresentUiCorrection;
// The Present hook point as the evaluate hooks and the reporting sites ask
// for it: selected AND in a session it serves.  A Direct3D 11 session is
// served on the native route only (present_path.hpp RunPresentPath, through
// the bridge); on the foreign route the D3D12 evaluates are a third-party
// tool's, no present runs NR for them, so they keep the Upscaled hook point,
// and under DX11Source=off (the route stays undecided) the addon is inert.
// The verdict, the card and the DLSS hint follow it: the D3D12-only build
// once reported path=present while the D3D11 bridge ran the Upscaled path
// on 239 of 240 evaluates.
inline bool PresentHookServes(bool = true) {
  // Vulkan (v8.1): the Present hook point has no Vulkan path; the evaluates
  // keep Upscaled (vulkan_path.hpp counts vk[present_fallback=]).
  return (stages::Current().Count(stages::Point::Present) != 0
          || screenshot::WantsFinalPresent())
         && !vulkan_present_seen.load(std::memory_order_relaxed)
         && (!D3D11OnlySession() || Dx11NativeRoute());
}
