#undef NVSDK_NGX_Parameter_SetUI
#undef NVSDK_NGX_Parameter_SetI
#undef NVSDK_NGX_Parameter_GetF
#undef NVSDK_NGX_Parameter_GetUI
#undef NVSDK_NGX_Parameter_GetI
